/** Mirrors ROLES in backend/app/models/user.py, lowest to highest. The backend
 * enforces every role check; the frontend only hides controls. */
export const ROLES = ['viewer', 'labeller', 'admin'] as const;
export type Role = typeof ROLES[number];

export interface User {
  id: number;
  email: string;
  name: string | null;
  role: Role;
  is_active: boolean;
  created_at: string;
  last_login_at: string | null;
}

export const hasRole = (user: User | null, minRole: Role): boolean =>
  user != null && ROLES.indexOf(user.role) >= ROLES.indexOf(minRole);

import { createContext, useContext } from 'react';
import type { Role, User } from '../types/User';

export interface AuthState {
  user: User;
  can: (minRole: Role) => boolean;
  signOut: () => Promise<void>;
}

export const AuthContext = createContext<AuthState | null>(null);

/** Only usable under AuthProvider, which renders children only once signed in. */
export function useAuth(): AuthState {
  const auth = useContext(AuthContext);
  if (auth == null) throw new Error('useAuth must be used inside AuthProvider');
  return auth;
}

import { useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { fetchMe, logout } from '../services/api';
import type { MeResult } from '../services/api';
import { AuthContext } from '../hooks/useAuth';
import type { AuthState } from '../hooks/useAuth';
import { hasRole } from '../types/User';
import SignIn from '../pages/SignIn';

/** Gates the whole app on /api/auth/me: children render only when signed in. */
export default function AuthProvider({ children }: { children: ReactNode }) {
  const [me, setMe] = useState<MeResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchMe()
      .then(setMe)
      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'));
  }, []);

  const auth = useMemo<AuthState | null>(() => {
    if (me?.status !== 'signed_in') return null;
    return {
      user: me.user,
      can: (minRole) => hasRole(me.user, minRole),
      signOut: async () => {
        await logout();
        setMe({ status: 'signed_out' });
      },
    };
  }, [me]);

  if (error) return <SignIn error={error} />;
  if (me == null) return null;
  if (auth == null) return <SignIn disabled={me.status === 'disabled'} />;
  return <AuthContext.Provider value={auth}>{children}</AuthContext.Provider>;
}

